'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var gfill = require( '@stdlib/blas/ext/base/gfill' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dkmeansInitRandomPartition = require( './../lib' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];

var options = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} M - number of data points
* @param {PositiveInteger} N - number of features
* @param {PositiveInteger} k - number of clusters
* @returns {Function} benchmark function
*/
function createBenchmark( order, M, N, k ) {
	var LDX;
	var LDO;
	var out;
	var W;
	var x;

	out = new Float64Array( k*N );
	W = new Int32Array( k );
	x = uniform( M*N, -100.0, 100.0, options );
	if ( order === 'row-major' ) {
		LDX = N;
		LDO = N;
	} else {
		LDX = M;
		LDO = k;
	}

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var c;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			// Reset the per-cluster counts, as the implementation expects a zero-initialized workspace:
			gfill( k, 0, W, 1 );
			c = dkmeansInitRandomPartition( order, M, N, k, x, LDX, out, LDO, W, 1 );
			if ( isnan( c[ i%( k*N ) ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( c[ 0 ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var M;
	var N;
	var k;
	var i;
	var f;

	min = 1; // 10^min
	max = 4; // 10^max

	// Benchmark: vary order with defaults k=2, M=100, N=2...
	for ( i = 0; i < LAYOUTS.length; i++ ) {
		f = createBenchmark( LAYOUTS[ i ], 100, 2, 2 );
		bench( format( '%s::vary_order:order=%s,k=2,M=100,N=2', pkg, LAYOUTS[ i ] ), f );
	}

	// Benchmark: vary number of data points (M) with defaults k=2, N=2...
	for ( i = min; i <= max; i++ ) {
		M = pow( 10, i );
		f = createBenchmark( 'row-major', M, 2, 2 );
		bench( format( '%s::vary_M:order=row-major,k=2,M=%d,N=2', pkg, M ), f );
	}

	// Benchmark: vary number of features (N) with defaults k=2, M=10...
	for ( i = min; i <= max; i++ ) {
		N = pow( 10, i );
		f = createBenchmark( 'row-major', 10, N, 2 );
		bench( format( '%s::vary_N:order=row-major,k=2,M=10,N=%d', pkg, N ), f );
	}

	// Benchmark: vary number of clusters (k) with defaults M=1000, N=2...
	for ( i = 1; i <= 4; i++ ) {
		k = pow( 2, i );
		f = createBenchmark( 'row-major', 1000, 2, k );
		bench( format( '%s::vary_k:order=row-major,k=%d,M=1000,N=2', pkg, k ), f );
	}
}

main();
